def one_line_per_expense(apps, schema_editor):
    """Every existing expense gets one line with its own amount, VAT and
    category, so the totals per year and per category stay the same
    (huismus-intern/besluiten.md, 2026-11-02: approved by Arne). The
    description stays on the expense; the line's is empty."""
    Expense = apps.get_model("expenses", "Expense")
    ExpenseLine = apps.get_model("expenses", "ExpenseLine")
    ExpenseLine.objects.bulk_create(
        ExpenseLine(
            expense_id=expense.pk,
            position=0,
            amount_cents=expense.amount_cents,
            vat_info_cents=expense.vat_info_cents,
            category_id=expense.category_id,
        )
        for expense in Expense.objects.all()
    )


def category_back_from_the_lines(apps, schema_editor):
    """Backwards: an expense takes the category of its first line that has
    one; the categories of its other lines are lost, as is every line's
    description. Its amount was never changed."""
    Expense = apps.get_model("expenses", "Expense")
    ExpenseLine = apps.get_model("expenses", "ExpenseLine")
    for expense in Expense.objects.all():
        line = (
            ExpenseLine.objects.filter(expense_id=expense.pk, category__isnull=False)
            .order_by("position", "pk")
            .first()
        )
        if line is not None:
            Expense.objects.filter(pk=expense.pk).update(category_id=line.category_id)


